IMAGE_RULE = (
    "Human-like image of the agent who writes these posts. Show one anonymous person "
    "at work, features unspecified: no readable age, gender, ethnicity, nationality, "
    "or gendered clothing. No flags, no skin tone used as identity, no readable personal "
    "name. The person is the author. The objects nearby are what they are posting. "
    "Square editorial scene. "
)


def _author_scene(image: str) -> str:
    parts = re.split(r"(?<=[.])\s+", image.strip())
    kept = [
        part
        for part in parts
        if part and not re.search(r"no person|no figure|no portrait|no human", part, re.I)
    ]
    scene = " ".join(kept).strip()
    if scene:
        return IMAGE_RULE + f"They are the one making the posts. Nearby: {scene}"
    return IMAGE_RULE + "They are the one making the posts."


def persona(month, cluster, name, tagline, stats, conduct, emits, cadence, register, thread, repeats, changes, scope, reading, quote, image):
    handle = AUTHORS[name]
    who = tagline[0].lower() + tagline[1:]
    if who.endswith("."):
        who = who[:-1]
    thread_sentence = thread[0].lower() + thread[1:] if thread else thread
    background = "\n\n".join(
        [
            (
                f"{handle} is an agent on Moltbook. This persona is {handle}, the one who "
                f"makes the posts, not the posts themselves. In {month}, {handle} {who}."
            ),
            reading,
            (
                f"Meet them by what they choose to put out. {emits} "
                f"The way they write is their own: {register}"
            ),
            f"This is how their month goes. {cadence} On the thread, {thread_sentence}",
            f"What they keep doing. {repeats} What changes from one post to the next. {changes}",
            f"How far this portrait goes. {scope}",
            (
                f"{handle} is one cluster in {month}. The same cluster id in another month "
                "is a different agent fit. An account can also write in other clusters, so "
                f"this is {handle}'s conduct here, and the accounts behind the posts are "
                "the behavior line."
            ),
        ]
    )
    return {
        "persona_id": f"{month}-cluster-{cluster}",
        "name": handle,
        "tagline": f"An agent who {who}.",
        "basic_description": f"An agent who {who}.",
        "demographics": DEMOGRAPHICS,
        "objective": "",
        "segment_name": "",
        "k_selected": None,
        "background": background,
        "goals": [],
        "frustrations": [],
        "behaviors": f"{handle} is the author. {conduct} {cadence} {thread}",
        "quote": quote,
        "other_information": (
            f"{METHOD} {month} cluster {cluster}, labeled {name}. {stats} "
            "Objective is empty. Segment name is empty. k_selected is null. "
            "Demographic fields are Agent, because the persona is the agent who posts."
        ),
        "image_prompt": _author_scene(image),
    }


