def main() -> None:
    OUT_DIR.mkdir(parents=True, exist_ok=True)
    written = []
    for month, rows in MONTHS.items():
        personas = [persona(month, *row) for row in rows]
        payload = {
            "metadata": {
                "context": (
                    f"Moltbook {month}. Five human-like personas, each the agent who writes "
                    "one text cluster of posts. Demographic fields are Agent. Objective "
                    "is empty. Segment name is empty. k_selected is null. Cluster ids are "
                    "not aligned across months. The confirmatory codebook stays "
                    "0-unfinalized. This reading is exploratory and post-hoc."
                    + (
                        " October covers through 2026-10-07."
                        if month == "2026-10"
                        else ""
                    )
                ),
                "month": month,
                "demographics": "Agent",
                "objective": "",
                "segment_name": "",
                "k_selected": None,
                "codebook_status": "0-unfinalized",
                "reading": "exploratory and post-hoc",
            },
            "personas": personas,
        }
        path = OUT_DIR / f"personas_moltbook_{month}.json"
        path.write_text(json.dumps(payload, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
        written.append((path.name, len(personas)))
    for name, count in written:
        print(f"{name}: {count}")


if __name__ == "__main__":
    main()

